class BinaryDataProcessor: 
    def __init__(self, binary_string):
        """
        Initialize the class with a binary string and clean it by removing all non 0 or 1 characters.
        """
        self.binary_string = binary_string
        self.clean_non_binary_chars()

    def clean_non_binary_chars(self):
        """
        Clean the binary string by removing all non 0 or 1 characters.
        >>> bdp = BinaryDataProcessor("01101000daf3e4r01100101011011000110110001101111")
        >>> bdp.clean_non_binary_chars()
        >>> bdp.binary_string
        '0110100001100101011011000110110001101111'

        """
        self.binary_string = ''.join(filter(lambda x: x in '01', self.binary_string))

    def calculate_binary_info(self):
        """
        Calculate the binary string information, including the percentage of 0 and 1, and the total length of the binary string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.calculate_binary_info()
        {'Zeroes': 0.475, 'Ones': 0.525, 'Bit length': 40}

        """
        count_0 = self.binary_string.count('0')
        count_1 = self.binary_string.count('1')
        total_length = len(self.binary_string)

        if total_length == 0:
            return {
                'Zeroes': 0.0,
                'Ones': 0.0,
                'Bit length': 0
            }

        return {
            'Zeroes': count_0 / total_length,
            'Ones': count_1 / total_length,
            'Bit length': total_length
        }

    def convert_to_ascii(self):
        """
        Convert the binary string to ascii string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_ascii()
        'hello'

        """
        chars = []
        for i in range(0, len(self.binary_string), 8):
            byte = self.binary_string[i:i+8]
            if len(byte) != 8:
                raise ValueError(f"Invalid length of byte at position {i}: {len(byte)} bits")
            try:
                char_code = int(byte, 2)
                chars.append(chr(char_code))
            except Exception as e:
                raise ValueError(f"Failed to convert byte to character: {e}")
        return ''.join(chars)

    def convert_to_utf8(self):
        """
        Convert the binary string to utf-8 string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_utf8()
        'hello'

        """
        # Validate that the binary string length is a multiple of 8
        if len(self.binary_string) % 8 != 0:
            raise ValueError(f"Incomplete byte sequence: {len(self.binary_string)} bits must be a multiple of 8")

        # Convert binary string to bytes
        try:
            byte_data = bytes(int(self.binary_string[i:i+8], 2) for i in range(0, len(self.binary_string), 8))
        except ValueError as e:
            raise ValueError(f"Failed to convert binary string to bytes: {e}")

        # Decode bytes as UTF-8
        try:
            return byte_data.decode('utf-8')
        except UnicodeDecodeError as e:
            raise ValueError(f"Incomplete or invalid UTF-8 sequence: {e}")
